body:
named: nb_cli_enqueue_change_f

helpful for such CLI commands：

DEFPY_YANG (my_slot_threadhold, my_slot_threadhold_cmd, "threadhold {"
	" high-cpu (0-100)$hcv    | high-cpu-desert (0-100)$hcd    |"
	" high-memory (0-100)$hmv | high-memory-desert (0-100)$hmd |"
	" high-flash (0-100)$hfv  | high-flash-desert (0-100)$hfd  |"
	" high-temp (0-100)$htv   | high-temp-desert (0-100)$htd   |"
	" low-temp (-100-100)$ltv | low-temp-desert (-100-100)$ltd }",
	... )
{
	const char *xpath = VTY_CURR_XPATH; //slot -or- subslot
	struct lyd_node *dnode = get_slot_derived_from(vty, VTY_CURR_XPATH, "card-with-cpu");
	DEVM_CHK_DO(!dnode, return CMD_WARNING_CONFIG_FAILED);
	if(hcv_str) nb_cli_enqueue_change_f(vty, xpath, "/config/cpu-tca/high-cpu-thr",              NB_OP_MODIFY, hcv_str);
	if(hcd_str) nb_cli_enqueue_change_f(vty, xpath, "/config/cpu-tca/high-cpu-desert-thr",       NB_OP_MODIFY, hcd_str);
	if(hmv_str) nb_cli_enqueue_change_f(vty, xpath, "/config/memory-tca/high-memory-thr",        NB_OP_MODIFY, hmv_str);
	if(hmd_str) nb_cli_enqueue_change_f(vty, xpath, "/config/memory-tca/high-memory-desert-thr", NB_OP_MODIFY, hmd_str);
	if(hfv_str) nb_cli_enqueue_change_f(vty, xpath, "/config/flash-tca/high-flash-thr",          NB_OP_MODIFY, hfv_str);
	if(hfd_str) nb_cli_enqueue_change_f(vty, xpath, "/config/flash-tca/high-flash-desert-thr",   NB_OP_MODIFY, hfd_str);
	if(htv_str) nb_cli_enqueue_change_f(vty, xpath, "/config/temp-tca/high-temp-thr",            NB_OP_MODIFY, htv_str);
	if(htd_str) nb_cli_enqueue_change_f(vty, xpath, "/config/temp-tca/high-temp-desert-thr",     NB_OP_MODIFY, htd_str);
	if(ltv_str) nb_cli_enqueue_change_f(vty, xpath, "/config/temp-tca/low-temp-thr",             NB_OP_MODIFY, ltv_str);
	if(ltd_str) nb_cli_enqueue_change_f(vty, xpath, "/config/temp-tca/low-temp-desert-thr",      NB_OP_MODIFY, ltd_str);
	return nb_cli_apply_changes(vty);
}

If using nb_cli_dequeue_change, it requires twice the amount of code and additional xpath combinations on stack
